import heapq

def match(orders):
    trades = []
    resting = {}  # id -> [side, price, qty, ts]
    buy_heap = []  # entries: (-price, ts, id)
    sell_heap = []  # entries: (price, ts, id)

    ts_counter = 0

    def clean_top(heap):
        while heap:
            top = heap[0]
            oid = top[2]
            if oid not in resting or resting[oid][2] <= 0:
                heapq.heappop(heap)
            else:
                return top
        return None

    for order in orders:
        ts_counter += 1
        ts = ts_counter

        if order[0] == 'cancel':
            _, oid = order
            if oid in resting:
                del resting[oid]
            continue

        if order[0] == 'limit':
            _, oid, side, price, qty = order
            remaining = qty
            is_market = False
        elif order[0] == 'ioc':
            _, oid, side, price, qty = order
            remaining = qty
            is_market = False
        elif order[0] == 'market':
            _, oid, side, qty = order
            remaining = qty
            price = None
            is_market = True
        else:
            continue

        if side == 'buy':
            opp_heap = sell_heap
        else:
            opp_heap = buy_heap

        while remaining > 0:
            top = clean_top(opp_heap)
            if top is None:
                break

            if side == 'buy':
                opp_price = top[0]  # sell heap entries: (price, ts, id)
            else:
                opp_price = -top[0]  # buy heap entries: (-price, ts, id)

            if not is_market:
                if side == 'buy':
                    if opp_price > price:
                        break
                else:
                    if opp_price < price:
                        break

            opp_id = top[2]
            opp_data = resting[opp_id]
            opp_qty = opp_data[2]

            trade_qty = min(remaining, opp_qty)

            if side == 'buy':
                buy_id = oid
                sell_id = opp_id
            else:
                buy_id = opp_id
                sell_id = oid

            trades.append([buy_id, sell_id, opp_price, trade_qty])

            remaining -= trade_qty
            opp_data[2] -= trade_qty

            if opp_data[2] <= 0:
                heapq.heappop(opp_heap)
                del resting[opp_id]

        if order[0] == 'limit' and remaining > 0:
            resting[oid] = [side, price, remaining, ts]
            if side == 'buy':
                heapq.heappush(buy_heap, (-price, ts, oid))
            else:
                heapq.heappush(sell_heap, (price, ts, oid))

    return trades

